<template><el-dialog v-model="visible" :title="editing?'编辑场景':'新建场景'" width="min(760px, 94vw)" destroy-on-close><el-form ref="formRef" :model="form" :rules="rules" label-position="top" v-loading="saving"><div class="config-grid"><el-form-item label="应用" prop="appId"><el-select v-model="form.appId" class="wide" placeholder="选择应用" @change="form.moduleId=''" ><el-option v-for="item in store.apps" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="模块" prop="moduleId"><el-select v-model="form.moduleId" class="wide" placeholder="选择模块"><el-option v-for="item in availableModules" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="场景名称" prop="name"><el-input v-model="form.name" maxlength="80" show-word-limit/></el-form-item><el-form-item label="场景 key" prop="key"><el-input v-model="form.key" :disabled="editing" placeholder="如 wms-customer-create"/></el-form-item><el-form-item label="优先级" prop="priority"><el-select v-model="form.priority" class="wide"><el-option v-for="item in ['P0','P1','P2','P3']" :key="item" :label="item" :value="item"/></el-select></el-form-item><el-form-item label="负责人"><el-input v-model="form.owner"/></el-form-item></div><el-form-item label="描述"><el-input v-model="form.description" type="textarea" :rows="3"/></el-form-item><el-form-item label="字段定义"><div class="wide"><el-table :data="form.fields" border max-height="260"><el-table-column label="字段名称" min-width="180"><template #default="{row}"><el-input v-model="row.name" placeholder="字段名"/></template></el-table-column><el-table-column label="必填" width="80"><template #default="{row}"><el-checkbox v-model="row.required"/></template></el-table-column><el-table-column label="示例值" min-width="220"><template #default="{row}"><el-input v-model="row.example" placeholder="用于生成样例数据"/></template></el-table-column><el-table-column width="70"><template #default="scope"><el-button link type="danger" @click="form.fields.splice(scope.$index,1)">删除</el-button></template></el-table-column></el-table><el-button style="margin-top:10px" @click="form.fields.push({name:'',required:false,example:''})">增加字段</el-button></div></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></template>
<script setup>
import{computed,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'../api';import{usePlatformStore}from'../stores/platform';const emit=defineEmits(['saved']),store=usePlatformStore(),visible=ref(false),editing=ref(false),saving=ref(false),formRef=ref();const form=reactive({appId:'',moduleId:'',name:'',key:'',priority:'P2',owner:'',description:'',fields:[]});const availableModules=computed(()=>store.modules.filter(item=>item.appId===form.appId));const rules={appId:[{required:true,message:'请选择应用',trigger:'change'}],moduleId:[{required:true,message:'请选择模块',trigger:'change'}],name:[{required:true,message:'请输入场景名称',trigger:'blur'}],key:[{required:true,message:'请输入场景 key',trigger:'blur'},{pattern:/^[a-z0-9]+(?:-[a-z0-9]+)*$/,message:'仅支持小写字母、数字和连字符',trigger:'blur'}],priority:[{required:true,message:'请选择优先级',trigger:'change'}]};
function open(item=null){editing.value=Boolean(item);Object.assign(form,{appId:item?.appId||'',moduleId:item?.moduleId||'',name:item?.name||'',key:item?.key||'',priority:item?.priority||'P2',owner:item?.owner||store.user?.displayName||'',description:item?.description||'',fields:(item?.dataSchema?.columns||[]).map(name=>({name,required:(item.dataSchema.required||[]).includes(name),example:item.dataSchema.example?.[name]??''}))});visible.value=true}
async function save(){if(!await formRef.value.validate().catch(()=>false))return;const fields=form.fields.map(item=>({...item,name:item.name.trim()})).filter(item=>item.name);if(new Set(fields.map(item=>item.name)).size!==fields.length)return ElMessage.warning('字段名称不能重复');const module=store.modules.find(item=>item.id===form.moduleId);const body={appId:form.appId,moduleId:form.moduleId,module:module?.name||'',name:form.name.trim(),key:form.key.trim(),priority:form.priority,owner:form.owner.trim(),description:form.description.trim(),dataSchema:{columns:fields.map(item=>item.name),required:fields.filter(item=>item.required).map(item=>item.name),example:Object.fromEntries(fields.map(item=>[item.name,item.example]))}};saving.value=true;try{const result=await api(editing.value?`/api/scenarios/${form.key}`:'/api/scenarios',{method:editing.value?'PUT':'POST',body:JSON.stringify(body)});visible.value=false;emit('saved',result);ElMessage.success(editing.value?'场景信息已更新':'场景已创建')}catch(e){ElMessage.error(e.message)}finally{saving.value=false}}
defineExpose({open});
</script>
